# -*- coding: utf-8 -*-
"""
ped20_cards_data.py
Thẻ Anki Master cho PED-20: Tiếp cận trẻ Ho và Khò khè theo lứa tuổi.
Basic-first (tầng 1 khung -> tầng 2 chi tiết) + thẻ ⚡ thuật toán + cloze phụ (giữ legacy_note_id).
"""


def _s(color, text):
    return '<span style="color:' + color + '"><b>' + text + '</b></span>'


def _R(t):
    return _s("#ff6b6b", t)


def _Y(t):
    return _s("#ffd43b", t)


def _G(t):
    return _s("#51cf66", t)


def _B(t):
    return _s("#74c0fc", t)


_BASE_NOTE_ID = 1789572911670  # note id của cloze đầu tiên trong APKG cũ; mỗi note cách nhau 2


def _legacy(i):
    return _BASE_NOTE_ID + 2 * i


_EBM = "🔬 EBM HIỆN ĐẠI & LÂM SÀNG"
_ALGO = "⚡ THUẬT TOÁN QUYẾT ĐỊNH"


def _basic(cid, sec, tier, cat, front, ans, why, src, algo=False):
    back = ("<b>🎯 Trả lời cốt lõi:</b><br>"
            + "<br>".join(str(i) + ") " + a for i, a in enumerate(ans, 1))
            + "<br><br><b>💡 Giải thích của AI:</b><br>" + why)
    return {
        "id": cid, "type": "basic", "track": "ebm", "section": sec, "category": cat, "tier": tier,
        "badge": _ALGO if algo else _EBM, "badge_class": "badge-algo" if algo else "badge-ebm",
        "front": front, "back": back,
        "extra": "📖 Nguồn: PED-20 RELEASE v1, " + src,
        "tags": ["PED-20", sec] + (["ALGO"] if algo else ["EBM"]),
    }


def _cz(cid, sec, i, text, src):
    return {"id": cid, "type": "cloze", "section": sec, "text": text,
            "extra": "📖 Nguồn: PED-20 RELEASE v1, " + src, "legacy_note_id": _legacy(i)}


